import type { CharacterData } from '../types';
import { getSmartArray, normalizeDisplayText, parseAttributeValue } from './common';
import { normalizeCharacterDataKeys } from './yamlParser';

export type MessageVariableScope = { type: 'message'; message_id: number };

type TavernApiLike = {
  getOrCreateChatWorldbook?: (chat: 'current', desiredName: string) => Promise<string>;
  createWorldbookEntries?: (bookName: string, entries: Array<Record<string, any>>) => Promise<unknown>;
  getChatWorldbookName?: (chat: 'current') => Promise<string | null>;
  getWorldbook?: (bookName: string) => Promise<Array<Record<string, any>>>;
};

function getApi(): TavernApiLike {
  return ((window as any).TavernHelper || (window.parent as any)?.TavernHelper || window) as TavernApiLike;
}

function ensureString(val: unknown): string {
  if (Array.isArray(val)) return val.join(', ');
  return val ? normalizeDisplayText(val) : '';
}

function stringifyArrayItem(val: unknown): string {
  if (val === undefined || val === null) return '';
  if (typeof val !== 'object' || Array.isArray(val)) return normalizeDisplayText(val);

  return Object.entries(val as Record<string, unknown>)
    .map(([key, value]) => {
      const normalizedKey = normalizeDisplayText(key);
      const normalizedValue =
        value && typeof value === 'object'
          ? stringifyArrayItem(value)
          : normalizeDisplayText(value);
      return normalizedKey && normalizedValue ? `${normalizedKey}: ${normalizedValue}` : '';
    })
    .filter(Boolean)
    .join('； ');
}

function ensureArray(val: unknown): string[] {
  if (Array.isArray(val)) return val.map(stringifyArrayItem).filter(Boolean);
  return getSmartArray(val);
}

function parseNamedEffectLine(line: string): readonly [string, string] | null {
  const normalized = normalizeDisplayText(line);
  if (!normalized) return null;

  const bracketMatch = normalized.match(/^\[([^\]]+)\]\s*[：:]\s*(.*)$/);
  if (bracketMatch) {
    const key = normalizeDisplayText(bracketMatch[1]);
    const value = normalizeDisplayText(bracketMatch[2]);
    if (key && value) return [key, value] as const;
    return null;
  }

  const splitIndex = normalized.search(/[：:]/);
  if (splitIndex <= 0) return null;

  const key = normalizeDisplayText(normalized.slice(0, splitIndex));
  const value = normalizeDisplayText(normalized.slice(splitIndex + 1));
  if (!key || !value) return null;

  return [key, value] as const;
}

function parseEffectMap(effectVal: unknown): Record<string, string> {
  if (effectVal && typeof effectVal === 'object' && !Array.isArray(effectVal)) {
    const effectObj = effectVal as Record<string, unknown>;
    return Object.fromEntries(
      Object.entries(effectObj)
        .map(([key, value]) => [normalizeDisplayText(key), ensureString(value).trim()] as const)
        .filter(([key, value]) => key.length > 0 && value.length > 0),
    );
  }

  const text = ensureString(effectVal).replace(/\r\n/g, '\n').trim();
  if (!text) return {};

  const lines = text
    .split('\n')
    .map(line => line.trim())
    .filter(Boolean);

  const effectMap: Record<string, string> = {};
  const remains: string[] = [];

  lines.forEach(line => {
    const named = parseNamedEffectLine(line);
    if (named) {
      const [key, value] = named;
      effectMap[key] = value;
      return;
    }

    remains.push(line);
  });

  if (Object.keys(effectMap).length > 0) {
    if (remains.length > 0) effectMap.描述 = remains.join('\n');
    return effectMap;
  }

  return { 描述: text };
}

function arrayToMap(
  arr: unknown,
  type: 'skill' | 'equip' | 'divinity' | 'backpack',
): Record<string, Record<string, any>> {
  const map: Record<string, Record<string, any>> = {};
  if (!Array.isArray(arr)) return map;

  arr.forEach(item => {
    if (!item || typeof item !== 'object') return;
    const anyItem = item as Record<string, any>;

    const itemName = ensureString(anyItem.名称 || anyItem.名稱).trim();
    if (!itemName) return;

    const { 名称, 名稱, ...rest } = anyItem;
    const processed: Record<string, any> = { ...rest };

    const tags = processed.标签 ?? processed.標籤;
    if (tags) processed.标签 = ensureArray(tags);
    else if (type === 'skill' || type === 'equip' || type === 'backpack') processed.标签 = [];
    delete processed.標籤;

    if (type !== 'divinity') {
      processed.效果 = parseEffectMap(processed.效果);
    }

    if (type === 'equip') {
      processed.品质 = processed.品质 || processed.品質 || '未知';
      processed.类型 = processed.分类 || processed.分類 || processed.类型 || processed.類型 || '未知';
      processed.描述 = processed.描述 || '';
      processed.位置 = processed.位置 || '';
    } else if (type === 'skill') {
      processed.品质 = processed.品质 || processed.品質 || '未知';
      processed.类型 = processed.类型 || processed.類型 || '未知';
      processed.消耗 = processed.消耗 ? ensureString(processed.消耗) : '';
      processed.描述 = processed.描述 || '';
    } else if (type === 'backpack') {
      const quantityRaw = processed.数量 ?? processed.數量 ?? processed.持有数量 ?? processed.持有數量 ?? 1;
      const quantityValue = Number(quantityRaw);
      processed.品质 = processed.品质 || processed.品質 || '未知';
      processed.类型 = processed.分类 || processed.分類 || processed.类型 || processed.類型 || '未知';
      processed.数量 = Number.isFinite(quantityValue) && quantityValue > 0 ? quantityValue : 1;
      processed.描述 = processed.描述 || '';
    }

    map[itemName] = processed;
  });

  return map;
}

function mergeNamedMaps(...maps: Array<Record<string, Record<string, any>>>): Record<string, Record<string, any>> {
  const merged: Record<string, Record<string, any>> = {};

  maps.forEach(map => {
    Object.entries(map).forEach(([name, value]) => {
      const existing = merged[name];
      if (!existing) {
        merged[name] = { ...value };
        return;
      }

      const existingQty = Number(existing.数量);
      const nextQty = Number(value.数量);
      const mergedQty = (Number.isFinite(existingQty) ? existingQty : 0) + (Number.isFinite(nextQty) ? nextQty : 0);

      merged[name] = {
        ...existing,
        ...value,
        标签: Array.from(new Set([...ensureArray(existing.标签), ...ensureArray(value.标签)])),
        效果: {
          ...(existing.效果 && typeof existing.效果 === 'object' ? existing.效果 : {}),
          ...(value.效果 && typeof value.效果 === 'object' ? value.效果 : {}),
        },
        数量: mergedQty > 0 ? mergedQty : (value.数量 ?? existing.数量 ?? 1),
      };
    });
  });

  return merged;
}

function statusEffectsToMap(input: unknown): Record<string, Record<string, any>> {
  const map: Record<string, Record<string, any>> = {};

  const normalizeEffect = (effectName: string, raw: unknown) => {
    if (!effectName.trim() || !raw || typeof raw !== 'object') return;
    const effect = raw as Record<string, unknown>;
    const layerValue = Number(effect.层数 ?? 1);
    map[effectName] = {
      类型: ensureString(effect.类型).trim() || '特殊',
      效果: ensureString(effect.效果).trim(),
      层数: Number.isFinite(layerValue) && layerValue > 0 ? layerValue : 1,
      剩余时间: ensureString(effect.剩余时间).trim(),
      来源: ensureString(effect.来源).trim(),
    };
  };

  if (Array.isArray(input)) {
    input.forEach(item => {
      if (!item || typeof item !== 'object') return;
      const anyItem = item as Record<string, unknown>;
      const effectName = ensureString(anyItem.名称 || anyItem.效果名称 || anyItem.name).trim();
      normalizeEffect(effectName, anyItem);
    });
    return map;
  }

  if (input && typeof input === 'object') {
    Object.entries(input as Record<string, unknown>).forEach(([effectName, effectValue]) => {
      normalizeEffect(effectName, effectValue);
    });
  }

  return map;
}

function isRecord(value: unknown): value is Record<string, any> {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

function hasOwn(value: unknown, key: string): boolean {
  return isRecord(value) && Object.prototype.hasOwnProperty.call(value, key);
}

function createNewCharacterDefaults(): Record<string, any> {
  return {
    在场: true,
    生命层级: '第一层级/普通层级',
    等级: 1,
    种族: '未知',
    身份: [],
    职业: [],
    性格: '',
    喜爱: '',
    外貌: '',
    着装: '',
    属性: { 力量: 0, 敏捷: 0, 体质: 0, 智力: 0, 精神: 0 },
    状态效果: {},
    背包: {},
    技能: {},
    装备: {},
    登神长阶: {
      是否开启: false,
      神位: '',
      神国: { 名称: '', 描述: '' },
      要素: {},
      权能: {},
      法则: {},
    },
    命定契约: false,
    好感度: 0,
    心里话: '',
    背景故事: '',
  };
}

export function mergeCharacterIntoMvuData(data: CharacterData, currentVars: Mvu.MvuData): string {
  const normalizedData = normalizeCharacterDataKeys(data);
  const charName = normalizedData.姓名 || '未命名角色';

  currentVars.stat_data ??= {};
  currentVars.stat_data.关系列表 ??= {};
  const currentCharacter = currentVars.stat_data.关系列表[charName];
  const mvuData: Record<string, any> = isRecord(currentCharacter)
    ? { ...currentCharacter }
    : createNewCharacterDefaults();

  if (hasOwn(normalizedData, '生命层级')) {
    mvuData.生命层级 = normalizedData.生命层级 || '第一层级/普通层级';
  }
  if (hasOwn(normalizedData, '等级')) mvuData.等级 = parseInt(String(normalizedData.等级 ?? '1'), 10) || 1;
  if (hasOwn(normalizedData, '种族')) mvuData.种族 = normalizedData.种族 || '未知';
  if (hasOwn(normalizedData, '身份')) mvuData.身份 = ensureArray(normalizedData.身份);
  if (hasOwn(normalizedData, '职业')) mvuData.职业 = ensureArray(normalizedData.职业);
  if (hasOwn(normalizedData, '性格')) mvuData.性格 = ensureString(normalizedData.性格).trim();
  if (hasOwn(normalizedData, '喜爱')) mvuData.喜爱 = ensureString(normalizedData.喜爱).trim();
  if (hasOwn(normalizedData, '外貌特质')) mvuData.外貌 = ensureString(normalizedData.外貌特质).trim();
  if (hasOwn(normalizedData, '衣物装饰')) mvuData.着装 = ensureString(normalizedData.衣物装饰).trim();
  if (hasOwn(normalizedData, '背景故事')) mvuData.背景故事 = normalizedData.背景故事 || '';

  if (isRecord(normalizedData.属性)) {
    const attributes = isRecord(mvuData.属性) ? { ...mvuData.属性 } : {};
    (['力量', '敏捷', '体质', '智力', '精神'] as const).forEach(key => {
      if (hasOwn(normalizedData.属性, key)) attributes[key] = parseAttributeValue(normalizedData.属性?.[key]);
    });
    mvuData.属性 = attributes;
  }

  if (hasOwn(normalizedData, '状态效果')) mvuData.状态效果 = statusEffectsToMap(normalizedData.状态效果);

  if (['背包', '道具', '物品', '特殊物品'].some(key => hasOwn(normalizedData, key))) {
    mvuData.背包 = mergeNamedMaps(
      arrayToMap(normalizedData.背包, 'backpack'),
      arrayToMap(normalizedData.道具, 'backpack'),
      arrayToMap(normalizedData.物品, 'backpack'),
      arrayToMap(normalizedData.特殊物品, 'backpack'),
    );
  }
  if (hasOwn(normalizedData, '技能')) mvuData.技能 = arrayToMap(normalizedData.技能, 'skill');
  if (hasOwn(normalizedData, '装备')) mvuData.装备 = arrayToMap(normalizedData.装备, 'equip');

  const divinityInput = isRecord(normalizedData.登神长阶) ? normalizedData.登神长阶 : {};
  const hasDivinityInput =
    hasOwn(normalizedData, '登神长阶') ||
    ['神位', '神国', '要素', '权能', '法则'].some(key => hasOwn(normalizedData, key));
  if (hasDivinityInput) {
    const divinity = isRecord(mvuData.登神长阶) ? { ...mvuData.登神长阶 } : {};
    divinity.是否开启 = true;

    if (hasOwn(divinityInput, '神位') || hasOwn(normalizedData, '神位')) {
      divinity.神位 = divinityInput.神位 || normalizedData.神位 || '';
    }
    if (hasOwn(divinityInput, '神国') || hasOwn(normalizedData, '神国')) {
      const sourceKingdom = divinityInput.神国 || normalizedData.神国 || {};
      const kingdom = isRecord(divinity.神国) ? { ...divinity.神国 } : {};
      if (hasOwn(sourceKingdom, '名称')) kingdom.名称 = sourceKingdom.名称 || '';
      if (hasOwn(sourceKingdom, '描述')) kingdom.描述 = sourceKingdom.描述 || '';
      divinity.神国 = kingdom;
    }
    if (hasOwn(divinityInput, '要素') || hasOwn(normalizedData, '要素')) {
      divinity.要素 = arrayToMap(divinityInput.要素 || normalizedData.要素, 'divinity');
    }
    if (hasOwn(divinityInput, '权能') || hasOwn(normalizedData, '权能')) {
      divinity.权能 = arrayToMap(divinityInput.权能 || normalizedData.权能, 'divinity');
    }
    if (hasOwn(divinityInput, '法则') || hasOwn(normalizedData, '法则')) {
      divinity.法则 = mergeNamedMaps(
        arrayToMap(normalizedData.法则, 'divinity'),
        arrayToMap(divinityInput.法则, 'divinity'),
      );
    }
    mvuData.登神长阶 = divinity;
  }

  currentVars.stat_data.关系列表[charName] = mvuData;

  return charName;
}

async function waitForCondition(
  predicate: () => boolean | Promise<boolean>,
  timeoutMs = 2500,
  intervalMs = 50,
): Promise<boolean> {
  const startedAt = Date.now();
  while (Date.now() - startedAt < timeoutMs) {
    if (await predicate()) return true;
    await new Promise(resolve => setTimeout(resolve, intervalMs));
  }
  return false;
}

export async function importToMvuVariables(data: CharacterData, targetScope: MessageVariableScope): Promise<void> {
  await waitGlobalInitialized('Mvu');
  const currentVars = Mvu.getMvuData(targetScope);
  const characterName = mergeCharacterIntoMvuData(data, currentVars);

  const writeResult = Promise.resolve(Mvu.replaceMvuData(currentVars, targetScope));
  const writeSettled = writeResult.then(
    () => true,
    error => {
      throw error;
    },
  );
  const readBackVerified = waitForCondition(() =>
    _.has(Mvu.getMvuData(targetScope), `stat_data.关系列表.${characterName}`),
  );

  const result = await Promise.race([
    writeSettled.then(() => 'settled' as const),
    readBackVerified.then(verified => (verified ? ('verified' as const) : ('timeout' as const))),
  ]);

  if (result === 'verified') {
    void writeResult.catch(error => console.error('[CharInfo Viewer] MVU write rejected after read-back success:', error));
    return;
  }
  if (result === 'settled') return;

  await writeResult;
}

function stripCharInfoWrapper(originalYaml: string): string {
  const content = String(originalYaml ?? '').trim();
  const wrapped = content.match(/^<char_info\b[^>]*>\s*([\s\S]*?)\s*<\/char_info>$/i);
  return (wrapped?.[1] ?? content).trim();
}

function formatWorldbookContent(originalYaml: string): string {
  const content = stripCharInfoWrapper(originalYaml);
  if (!content) return '---';
  return /^---(?:\r?\n|$)/.test(content) ? content : `---\n${content}`;
}

export async function saveToChatWorldbook(
  data: CharacterData,
  originalYaml: string,
): Promise<Record<string, unknown>> {
  const api = getApi();
  if (typeof api.getOrCreateChatWorldbook !== 'function' || typeof api.createWorldbookEntries !== 'function') {
    throw new Error('未检测到 Worldbook API。');
  }

  const normalizedData = normalizeCharacterDataKeys(data);
  const characterName = normalizedData.姓名 || '未命名角色';
  const shortName = characterName.split(/[·\s]/)[0];
  const lorebookKey = shortName && shortName.trim().length > 0 ? shortName : characterName;
  const content = formatWorldbookContent(originalYaml);

  console.info('[CharInfo Viewer] Preparing chat worldbook entry', {
    characterName,
    lorebookKey,
    contentStartsWithDocumentMarker: content.startsWith('---'),
  });

  let bookName: string | null = null;
  if (typeof api.getChatWorldbookName === 'function') {
    bookName = await api.getChatWorldbookName('current');
  }

  if (!bookName) {
    const now = new Date();
    const timeStr = `${now.getFullYear()}_${String(now.getMonth() + 1).padStart(2, '0')}_${String(now.getDate()).padStart(2, '0')}_${now.getHours()}h_${now.getMinutes()}m_${now.getSeconds()}s`;
    const desiredName = `命定之诗-charinfo-Chat_Book_${timeStr}`;
    bookName = await api.getOrCreateChatWorldbook('current', desiredName);
  }

  const newEntry = {
    name: characterName,
    enabled: true,
    strategy: { type: 'selective', keys: [lorebookKey] },
    position: { type: 'after_character_definition', order: 601 },
    recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
    content,
  };

  console.info('[CharInfo Viewer] Creating chat worldbook entry', { bookName, entry: newEntry });
  const writeResult = Promise.resolve(api.createWorldbookEntries(bookName, [newEntry]));
  const writeSettled = writeResult.then(
    apiResult => ({ kind: 'settled' as const, apiResult }),
    error => {
      throw error;
    },
  );

  const readBackVerified =
    typeof api.getWorldbook === 'function'
      ? waitForCondition(async () => {
          const entries = await api.getWorldbook!(bookName!);
          return entries.some(entry => entry?.name === characterName && entry?.content === content);
        }).then(verified => ({ kind: verified ? ('verified' as const) : ('timeout' as const) }))
      : new Promise<{ kind: 'unavailable' }>(() => undefined);

  const result = await Promise.race([writeSettled, readBackVerified]);
  if (result.kind === 'settled') {
    console.info('[CharInfo Viewer] Chat worldbook entry created', { bookName, apiResult: result.apiResult });
    return { bookName, entry: newEntry, apiResult: result.apiResult };
  }
  if (result.kind === 'verified') {
    void writeResult.catch(error =>
      console.error('[CharInfo Viewer] Worldbook write rejected after read-back success:', error),
    );
    console.info('[CharInfo Viewer] Chat worldbook entry verified by read-back', { bookName, characterName });
    return { bookName, entry: newEntry, apiResult: 'verified-by-readback' };
  }

  const apiResult = await writeResult;
  console.info('[CharInfo Viewer] Chat worldbook entry created after read-back timeout', { bookName, apiResult });
  return { bookName, entry: newEntry, apiResult };
}
